272		content = clean(content)
273		constraints = clean(constraints)
274		followOwner = clean(followOwner)
275		if err := requireNonEmpty("事项内容", content); err != nil {
276			return Item{}, err
277		}
278		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
279			return Item{}, err
280		}
281		if !severity.valid() {
282			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
283		}
284	
285		var updated Item
286		err := svc.store.mutate(func(d *Data) error {
287			it, _ := findItem(d, itemID)
288			if it == nil {
289				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
290			}
291			sh, _ := findShift(d, it.CurrentShiftID)
292			if sh == nil || sh.Closed {
