364	// CloseShift 结束班次。任一接班交接存在未确认接收的事项（待处理、退回、
365	// 处理结果缺失或无法识别）时不允许结束，其他交接已完成也不能放行；空清单
366	// 交接视为已完成，可以结束。
367	// 结束成功时把在班事项（本班新增与已接收，含结束前已关闭者）冻结为结束时记录；
368	// 校验或保存失败时不留下任何记录，班次保持进行中，也不改变交接结果、
369	// 事项归属与已保存的处理经过。
370	func (svc *Service) CloseShift(shiftID string) (Shift, error) {
371		shiftID = clean(shiftID)
372		var result Shift
373		err := svc.store.mutate(func(d *Data) error {
374			sh, _ := findShift(d, shiftID)
375			if sh == nil {
376				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
377			}
378			if sh.Closed {
379				return fmt.Errorf("%w：班次 %s 已结束", ErrShiftClosed, sh.ID)
380			}
381			for i := range d.Handovers {
382				h := &d.Handovers[i]
383				if h.ToShiftID == sh.ID && !h.Completed() {
384					return fmt.Errorf("%w：接班交接 %s 仍有未确认接收的事项，班次不能结束",
385						ErrHandoverState, h.ID)
386				}
387			}
388			now := svc.now()
389			sh.Closed = true
390			sh.ClosedAt = &now
391	
392			// 冻结结束时在班的全部事项。退回或未确认的交接事项当前班次仍在交班
393			// 班次，不会被快照；结束前已关闭的事项保留关闭人与关闭时间。
394			record := &ShiftCloseRecord{Items: []CloseItemSnapshot{}}
395			for i := range d.Items {
396				it := &d.Items[i]
397				if it.CurrentShiftID != sh.ID {
398					continue
399				}
400				record.Items = append(record.Items, CloseItemSnapshot{
401					ItemID:        it.ID,
402					Content:       it.Content,
403					Severity:      it.Severity,
404					Constraints:   it.Constraints,
405					FollowOwner:   it.FollowOwner,
406					Closed:        it.Closed,
407					ClosedAt:      it.ClosedAt,
408					CloseOperator: it.CloseOperator,
409				})
410			}
411			sort.Slice(record.Items, func(i, j int) bool { return record.Items[i].ItemID < record.Items[j].ItemID })
412			sh.CloseRecord = record
413	
414			result = *sh
415			return nil
416		})
417		return result, err
418	}
