711		if ea.Rounds[0].Reason != "信息不全，需补充图纸" {
712			t.Fatalf("第一轮退回原因不得覆盖：%+v", ea.Rounds[0])
713		}
714		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "签字已补齐"); err != nil {
715			t.Fatalf("resubmit2: %v", err)
