944			cur.Constraints != "新限制" || cur.FollowOwner != "新负责人" || !cur.Closed {
945			t.Fatalf("item-show 应展示最新状态：%+v", cur)
946		}
947	
948		// 渲染文本应标明“结束时记录”并区分“最新状态”。
949		text := handoverReportText(t, f.svc, a.ID)
950		if !strings.Contains(text, "结束时记录") {
951			t.Fatalf("报告应标明结束时记录")
952		}
