1380		}
1381	
1382		it, _ := f.svc.GetItem(idA)
1383		if it.CurrentShiftID != a.ID || it.FollowOwner != "李四" {
1384			t.Fatalf("失败处理不得移动事项班次或改负责人：%+v", it)
1385		}
