1519	// TestResubmitStateAndInputRules：只有退回项可重新提交；待处理、已确认、
1520	// 继续跟踪都报状态错误且不写入补充；操作人必填、纯空格补充视为空。
1521	func TestResubmitStateAndInputRules(t *testing.T) {
1522		f := newFixture(t)
