1532		ea := findEntryOf(t, got, idA)
1533		if len(ea.Rounds) != 0 || ea.Status != EntryPending {
1534			t.Fatalf("状态错误时不应写入补充或退回记录：%+v", ea)
1535		}
1536	
1537		// 已确认项重新提交：状态错误。
1538		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionConfirm, "李四", "", "", ""); err != nil {
1539			t.Fatalf("confirm: %v", err)
1540		}
1541		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "补充内容"); !errors.Is(err, ErrHandoverState) {
1542			t.Fatalf("已确认项重新提交应报错，got %v", err)
1543		}
1544	
1545		// 继续跟踪项重新提交：状态错误。
1546		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionTrack, "李四", "", "盯住", "王五"); err != nil {
1547			t.Fatalf("track: %v", err)
1548		}
1549		if _, err := f.svc.ResubmitReturned(h.ID, idB, "张三", "补充内容"); !errors.Is(err, ErrHandoverState) {
1550			t.Fatalf("继续跟踪项重新提交应报错，got %v", err)
1551		}
1552	
1553		// 退回后：操作人缺失、纯空格补充均为输入错误，且不写入。idA/idB 都已接收，
1554		// 另起一套数据制造退回项。
1555		f2 := newFixture(t)
1556		a2, b2, items2 := prepareHandover(t, f2)
1557		h3, _ := f2.svc.CreateHandover(a2.ID, b2.ID)
